import{offlineAudioStore}from './quran-offline-store.js';
import{audioUrl}from './quran-data.js';
import{read,write}from './storage.js';
export function durationTimeline(durations){if(!Array.isArray(durations)||!durations.length||durations.some(d=>!Number.isFinite(d)||d<=0||d>3600))return null;let sum=0;const starts=durations.map(d=>{const start=sum;sum+=d;return start;});return sum<=86400?{durations,starts,total:sum}:null;}
export function timelinePosition(table,seconds){const point=Math.max(0,Math.min(seconds,table.total-.01));let index=table.starts.length-1;while(index>0&&table.starts[index]>point)index--;return {index,seconds:point-table.starts[index]};}
function probeDuration(url,signal){return new Promise(resolve=>{if(signal?.aborted||typeof Audio!=='function'){resolve(null);return;}const audio=new Audio();let timer;const finish=value=>{clearTimeout(timer);signal?.removeEventListener('abort',abort);audio.onloadedmetadata=audio.onerror=null;audio.pause();audio.removeAttribute('src');audio.load();resolve(Number.isFinite(value)&&value>0?value:null);};const abort=()=>finish(null);signal?.addEventListener('abort',abort,{once:true});audio.preload='metadata';audio.onloadedmetadata=()=>finish(audio.duration);audio.onerror=abort;timer=setTimeout(abort,12000);audio.src=url;audio.load();});}
export async function loadSurahDurations(surah,reciter,{signal,probe=probeDuration,offlineOnly=false}={}){if(typeof Audio!=='function'&&probe===probeDuration)return null;const key='quran-duration-v1:'+reciter+':'+surah.number,cache=read(key,null),count=surah.verses.length;const values=Array.isArray(cache)&&cache.length===count?cache.slice():Array(count).fill(null);const cached=durationTimeline(values);if(cached)return cached;let cursor=0,failed=false;await Promise.all(Array.from({length:3},async()=>{while(cursor<count&&!signal?.aborted&&!failed){const i=cursor++;if(Number.isFinite(values[i])&&values[i]>0&&values[i]<=3600)continue;let url=audioUrl(surah.verses[i].number,reciter,surah.number),blobUrl=null;if(offlineOnly){try{const blob=await offlineAudioStore.getAudio(url);if(blob){blobUrl=URL.createObjectURL(blob);url=blobUrl;}else{failed=true;return;}}catch{failed=true;return;}}let duration;try{duration=await probe(url,signal);}finally{if(blobUrl)URL.revokeObjectURL(blobUrl);}if(signal?.aborted)return;if(!Number.isFinite(duration)||duration<=0||duration>3600){failed=true;return;}values[i]=duration;}}));if(!signal?.aborted)write(key,values);return signal?.aborted?null:durationTimeline(values);}
